                 allValueSpans.forEach(span => span.innerText = 'N/A');
                 const allBars = document.querySelectorAll('.progress-bar-value');
                 allBars.forEach(bar => bar.style.width = '0%');
            }

            const firstSectionHeader = document.querySelector('.section:nth-child(1) .section-header');
            if (firstSectionHeader) {
                const content = firstSectionHeader.nextElementSibling;
                if (!content.classList.contains('expanded')) {
