                updateProgressBar('lisirou-lust-bar', 'lisirou-lust', null, char.性欲, 0, 100, 'var(--lust-color)');
                updateProgressBar('lisirou-misunderstanding-bar', 'lisirou-misunderstanding', null, char.误解指数, 0, 100, 'var(--misunderstanding-color)');
                updateProgressBar('lisirou-pleasure-bar', 'lisirou-pleasure', null, char.愉悦度, -1, 1, null);

                document.getElementById('lisirou-location').innerText = SafeGetValue(char, '当前位置', '未知');
                document.getElementById('lisirou-thought').innerText = SafeGetValue(char, '当前所想', '...');

            } else {
                 const allValueSpans = document.querySelectorAll('.value-main, .property-text-value');
                 allValueSpans.forEach(span => span.innerText = 'N/A');
                 const allBars = document.querySelectorAll('.progress-bar-value');
                 allBars.forEach(bar => bar.style.width = '0%');
            }

            const firstSectionHeader = document.querySelector('.section:nth-child(1) .section-header');
            if (firstSectionHeader) {
                const content = firstSectionHeader.nextElementSibling;
                if (!content.classList.contains('expanded')) {
                     toggleSection(firstSectionHeader);
                }
            }

        } catch (error) {
            console.error("Status bar error:", error);
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    function toggleSection(element) {
        if (!element) return;
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        arrow.innerText = isExpanded ? '▲' : '▼';
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
</html>
